/**
 * AI-SDLC: Product Definition as Code (PDaC) Graph & Cryptographic Drift Verifier
 */

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import {
  PdacDrift,
  PdacGraphOptions,
  PdacGraphResult,
  PdacNode,
  PdacSyncDetail,
  PdacSyncOptions,
  PdacSyncResult,
} from '../types/index.js';
import { walkMdFiles } from '../utils/fs.js';

export function computeCanonicalSha256(content: string): string {
  // Normalize newlines to LF for deterministic hashing
  const normalized = content.replace(/\r\n/g, '\n');
  return crypto.createHash('sha256').update(normalized, 'utf-8').digest('hex');
}

export function parseFrontmatterId(content: string): { id?: string; type?: string; title?: string } {
  const match = content.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!match) return {};

  const lines = match[1].split('\n');
  let id: string | undefined;
  let type: string | undefined;
  let title: string | undefined;

  for (const line of lines) {
    const parts = line.split(':');
    if (parts.length >= 2) {
      const key = parts[0].trim();
      const val = parts.slice(1).join(':').trim().replace(/^["']|["']$/g, '');
      if (key === 'id') id = val;
      if (key === 'type') type = val;
      if (key === 'title') title = val;
    }
  }

  return { id, type, title };
}

interface CitationEntry {
  targetId: string;
  expectedDigest?: string;
  anchor?: string;
  sourceFile: string;
}

export function extractCitations(content: string, sourceFile: string): CitationEntry[] {
  const citations: CitationEntry[] = [];
  const lines = content.split('\n');

  let inCitations = false;
  let currentTarget: string | null = null;
  let currentDigest: string | undefined;
  let currentAnchor: string | undefined;

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    if (line.startsWith('citations:')) {
      inCitations = true;
      continue;
    }

    if (inCitations) {
      if (line.endsWith(':') && !line.startsWith('- ') && !line.startsWith('id:') && !line.startsWith('digest:') && !line.startsWith('anchor:') && !line.startsWith('comment:')) {
        inCitations = false;
        if (currentTarget) {
          citations.push({ targetId: currentTarget, expectedDigest: currentDigest, anchor: currentAnchor, sourceFile });
          currentTarget = null;
          currentDigest = undefined;
          currentAnchor = undefined;
        }
        continue;
      }

      if (line.startsWith('- id:')) {
        if (currentTarget) {
          citations.push({ targetId: currentTarget, expectedDigest: currentDigest, anchor: currentAnchor, sourceFile });
        }
        currentTarget = line.split(':')[1].replace(/['"]/g, '').trim();
        currentDigest = undefined;
        currentAnchor = undefined;
      } else if (currentTarget) {
        if (line.startsWith('digest:')) {
          let dig = line.split(':').slice(1).join(':').replace(/['"]/g, '').trim();
          if (dig.startsWith('sha256:')) dig = dig.substring(7);
          currentDigest = dig;
        } else if (line.startsWith('anchor:')) {
          currentAnchor = line.split(':')[1].replace(/['"]/g, '').trim();
        }
      }
    }
  }

  if (currentTarget) {
    citations.push({ targetId: currentTarget, expectedDigest: currentDigest, anchor: currentAnchor, sourceFile });
  }

  return citations;
}



export function generatePdacReportMarkdown(
  nodes: PdacNode[],
  drifts: PdacDrift[],
  unresolvedCount: number
): string {
  const isOk = drifts.length === 0 && unresolvedCount === 0;
  const lines: string[] = [
    `# 🔒 PDaC Cryptographic Matrix and Drift Detection (Anti-Drift)`,
    ``,
    `> **Evaluation Date:** ${new Date().toISOString()}`,
    `> **Verdict:** ${isOk ? '✅ ALIGNED (0 Cryptographic drifts detected)' : `❌ DRIFT DETECTED (${drifts.length} Digest misalignments)`}`,
    ``,
    `---`,
    ``,
    `## 1. Canonical Baseline Nodes (${nodes.length})`,
    ``,
    `| Artifact ID | Type | Title | SHA-256 Digest (Baseline) |`,
    `| :--- | :--- | :--- | :--- |`,
  ];

  for (const n of nodes) {
    lines.push(`| **\`${n.id}\`** | \`${n.type}\` | ${n.title || 'Untitled'} | \`sha256:${n.digest.substring(0, 16)}...\` |`);
  }

  if (drifts.length > 0) {
    lines.push('');
    lines.push('---');
    lines.push('');
    lines.push('## 2. Cryptographic Drifts Detected (Status: STALE)');
    lines.push('');
    lines.push('| Consumer File | Cited ID | Expected Digest in Spec | Actual Digest in Baseline |');
    lines.push('| :--- | :--- | :--- | :--- |');
    for (const d of drifts) {
      lines.push(
        `| \`${d.sourceFile}\` | **\`${d.targetId}\`** | \`sha256:${d.expectedDigest.substring(0, 12)}...\` | \`sha256:${d.actualDigest.substring(0, 12)}...\` |`
      );
    }
  }

  return lines.join('\n');
}

export function verifyPdacGraph(options: PdacGraphOptions = {}): PdacGraphResult {
  const rootDir = options.rootDir || process.cwd();
  const allMdFiles = walkMdFiles(rootDir);

  const baselineMap = new Map<string, PdacNode>();
  const allCitations: CitationEntry[] = [];

  for (const file of allMdFiles) {
    try {
      const content = fs.readFileSync(file, 'utf-8');
      const { id, type, title } = parseFrontmatterId(content);
      const digest = computeCanonicalSha256(content);
      const relFile = path.relative(rootDir, file).replace(/\\/g, '/');

      if (id) {
        const citations = extractCitations(content, relFile);
        baselineMap.set(id, {
          id,
          type: type || 'artifact',
          filePath: relFile,
          title,
          digest,
          rawContent: content,
          citations: citations.map((c) => ({
            targetId: c.targetId,
            expectedDigest: c.expectedDigest,
            anchor: c.anchor,
          })),
        });
      }

      // Also collect citations from specs, sdd, delivery, and change directories (ignore templates/ and process/)
      const isDeliveryDoc =
        (relFile.startsWith('specs/') ||
          relFile.startsWith('sdd/') ||
          relFile.startsWith('delivery/') ||
          relFile.startsWith('changes/') ||
          relFile.includes('/specs/')) &&
        !relFile.includes('.template.');
      if (isDeliveryDoc) {
        const fileCitations = extractCitations(content, relFile);
        allCitations.push(...fileCitations);
      }
    } catch {
      // Ignore unparseable files
    }
  }

  const drifts: PdacDrift[] = [];
  let unresolvedCount = 0;

  for (const citation of allCitations) {
    const targetNode = baselineMap.get(citation.targetId);
    if (!targetNode) {
      unresolvedCount++;
      continue;
    }

    if (citation.expectedDigest) {
      if (citation.expectedDigest !== targetNode.digest) {
        drifts.push({
          sourceId: citation.sourceFile,
          targetId: citation.targetId,
          sourceFile: citation.sourceFile,
          expectedDigest: citation.expectedDigest,
          actualDigest: targetNode.digest,
        });
      }
    }
  }

  const nodes = Array.from(baselineMap.values());
  const reportMarkdown = generatePdacReportMarkdown(nodes, drifts, unresolvedCount);

  return {
    success: drifts.length === 0,
    totalNodes: nodes.length,
    totalEdges: allCitations.length,
    drifts,
    reportMarkdown,
  };
}

export function updateCitationsInContent(
  content: string,
  baselineMap: Map<string, PdacNode>,
  sourceFile: string,
  details: PdacSyncDetail[]
): { updatedContent: string; changed: boolean } {
  const lines = content.split(/\r?\n/);
  let changed = false;
  let inCitations = false;
  let currentTarget: string | null = null;
  const newLines: string[] = [];

  for (const rawLine of lines) {
    const trimmed = rawLine.trim();

    if (trimmed.startsWith('citations:')) {
      inCitations = true;
      newLines.push(rawLine);
      continue;
    }

    if (inCitations) {
      if (
        trimmed.endsWith(':') &&
        !trimmed.startsWith('- ') &&
        !trimmed.startsWith('id:') &&
        !trimmed.startsWith('digest:') &&
        !trimmed.startsWith('anchor:') &&
        !trimmed.startsWith('comment:')
      ) {
        inCitations = false;
        currentTarget = null;
        newLines.push(rawLine);
        continue;
      }

      if (trimmed.startsWith('- id:')) {
        currentTarget = trimmed.split(':')[1].replace(/['"]/g, '').trim();
        newLines.push(rawLine);
        continue;
      }

      if (currentTarget && trimmed.startsWith('digest:')) {
        const targetNode = baselineMap.get(currentTarget);
        if (targetNode) {
          let currentDig = trimmed.split(':').slice(1).join(':').replace(/['"]/g, '').trim();
          const hadShaPrefix = currentDig.startsWith('sha256:');
          if (hadShaPrefix) currentDig = currentDig.substring(7);
          const hasQuotes = trimmed.includes('"') || trimmed.includes("'");

          if (currentDig !== targetNode.digest) {
            const indent = rawLine.match(/^\s*/)?.[0] || '    ';
            const prefix = hadShaPrefix ? 'sha256:' : '';
            const val = `${prefix}${targetNode.digest}`;
            const newLine = hasQuotes ? `${indent}digest: "${val}"` : `${indent}digest: ${val}`;
            newLines.push(newLine);
            changed = true;
            details.push({
              sourceFile,
              targetId: currentTarget,
              previousDigest: currentDig,
              newDigest: targetNode.digest,
            });
            continue;
          }
        }
      }
    }

    newLines.push(rawLine);
  }

  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  return { updatedContent: newLines.join(eol), changed };
}

export function syncPdacDigests(options: PdacSyncOptions = {}): PdacSyncResult {
  const rootDir = options.rootDir || process.cwd();
  const allMdFiles = walkMdFiles(rootDir);
  const baselineMap = new Map<string, PdacNode>();

  for (const file of allMdFiles) {
    try {
      const content = fs.readFileSync(file, 'utf-8');
      const { id, type, title } = parseFrontmatterId(content);
      if (id) {
        const digest = computeCanonicalSha256(content);
        const relFile = path.relative(rootDir, file).replace(/\\/g, '/');
        baselineMap.set(id, {
          id,
          type: type || 'artifact',
          filePath: relFile,
          title,
          digest,
          rawContent: content,
          citations: [],
        });
      }
    } catch {
      // Ignore unparseable files
    }
  }

  const details: PdacSyncDetail[] = [];
  const updatedFiles: string[] = [];
  const candidateFiles: string[] = [];

  if (options.targetPath) {
    const fullTarget = path.isAbsolute(options.targetPath) ? options.targetPath : path.join(rootDir, options.targetPath);
    if (fs.existsSync(fullTarget)) {
      if (fs.statSync(fullTarget).isDirectory()) candidateFiles.push(...walkMdFiles(fullTarget));
      else candidateFiles.push(fullTarget);
    }
  } else {
    for (const file of allMdFiles) {
      const relFile = path.relative(rootDir, file).replace(/\\/g, '/');
      const isDeliveryDoc =
        (relFile.startsWith('specs/') ||
          relFile.startsWith('sdd/') ||
          relFile.startsWith('delivery/') ||
          relFile.startsWith('changes/') ||
          relFile.includes('/specs/')) &&
        !relFile.includes('.template.');
      if (isDeliveryDoc) candidateFiles.push(file);
    }
  }

  for (const file of candidateFiles) {
    try {
      const content = fs.readFileSync(file, 'utf-8');
      const relFile = path.relative(rootDir, file).replace(/\\/g, '/');
      const { updatedContent, changed } = updateCitationsInContent(content, baselineMap, relFile, details);
      if (changed) {
        fs.writeFileSync(file, updatedContent, 'utf-8');
        updatedFiles.push(relFile);
      }
    } catch {
      // Ignore unreadable or unwritable files
    }
  }

  return {
    success: true,
    syncedCount: details.length,
    updatedFiles,
    details,
  };
}
